const searchResult = $json;
const query = $('RAG Webhook Trigger').item.json.body.text;
const results = searchResult.results || [];

if (results.length === 0) {
  return [{
    json: {
      answer: `По вашему запросу "${query}" в корпоративной базе знаний нет документов, доступных для вашего уровня допуска (${$('RAG Webhook Trigger').item.json.body.security_context.Department}).`,
      sources_count: 0
    }
  }];
}

let contextText = results.map((r, i) => `[Источник ${i+1}]: ${r.text}`).join('\n\n');
let prompt = `Вопрос пользователя: "${query}"\n\nНайденная регламентная информация:\n${contextText}\n\nСформулируй краткий и точный ответ на основе приведенных регламентов типографии Fotoprint:`;

return [{
  json: {
    answer: `На основе регламентов Fotoprint:\n\n` + results.map(r => '• ' + r.text).join('\n\n'),
    prompt: prompt,
    sources_count: results.length,
    sources: results
  }
}];
